function formatDate(n,t,i){let r=String(t).padStart(2,"0"),u=String(i).padStart(2,"0");return`${n}-${r}-${u}`}function formDataAppendTime(n){let r=$("#timeUnit").val();n.append("TimeUnit",r);let t,i;switch(r){case"day":t=$("#startDate").val();i=$("#endDate").val();break;case"month":t=formatDate($("#startMonthYear").val(),$("#startMonthMonth").val(),1);i=formatDate($("#endMonthYear").val(),$("#endMonthMonth").val(),1);break;case"quarter":t=formatDate($("#startQuarterYear").val(),$("#startQuarterQuarter").val()*3-2,1);i=formatDate($("#endQuarterYear").val(),$("#endQuarterQuarter").val()*3-2,1);break;case"year":t=formatDate($("#startYearInput").val(),1,1);i=formatDate($("#endYearInput").val(),1,1)}return n.append("Start",t),n.append("End",i),n}